head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf00400";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf00400.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $('#paging7 table:first-child').attr('align', 'center');
        $c.util.getComponent('paging7').firstChild.setAttribute('align', 'center');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00400.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_srchWord_onkeydown
 * @description ipt_srchWord 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_srchWord_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        if(event.keyCode===13){$c.str.replaceAll(selfVar);await scwin.searchBizFormListByCond();}

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00400.ipt_srchWord_onkeydown' }); }
};

/**
 * @method
 * @name ipt_srchWord_onblur
 * @description ipt_srchWord 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_srchWord_onblur = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.str.replaceAll(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00400.ipt_srchWord_onblur' }); }
};

/**
 * @method
 * @name btn_searchBizFormListByCond_onclick
 * @description btn_searchBizFormListByCond 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchBizFormListByCond_onclick = async function(e){
    try {
        await scwin.searchBizFormListByCond()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf00400.btn_searchBizFormListByCond_onclick' }); }
};

/**
 * @method
 * @name grd_result_oncellclick
 * @description grd_result 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.fileDown(r["contnId"], r["attachFileNm"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};

/**
 * @method
 * @name span_48_onclick
 * @description 「닫 기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.span_48_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf00400.span_48_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_44_onclick
 * @description krxpage_pagenavigator_44 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_44_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_searchBizFormListByCondReq').set('pageIndex', pi);
        await scwin.tx_fn_searchBizFormListByCond();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldbnf00400.krxpage_pagenavigator_44_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchBizFormListByCond
 * @description search Biz Form List By Cond 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchBizFormListByCond = async function () {
    const sbmOptions = {
        id: "tx_fn_searchBizFormListByCond",
        method: "post",
        action: "/main/notice.do?method=searchNoticeList",
        ref: "dma_searchBizFormListByCondReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_44").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_searchBizFormListByCondReq').set('pageIndex', "1");
};

/**
 * @method
 * @name tx_fn_fileDown
 * @description file Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_fileDown = async function () {
    try { return await $c.data.downFile("/main/notice.do?method=downloadFile", "", ($c.util.getComponent("dma_fileDownReq") ? $c.util.getComponent("dma_fileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name searchBizFormListByCond
 * @description search Biz Form List By Cond 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchBizFormListByCond = async function () {
    const fm = (document.searchForm || { elements: [] });
    let _previewWindow;
    _previewWindow = $c.win.openPopup("/notice/notice.xml", { id: "popBizFormList", resizable: false, type: "pageFramePopup" }, ($c.util.getComponent("dma_searchBizFormListByCondReq") ? $c.util.getComponent("dma_searchBizFormListByCondReq").getJSON() : {}));
    fm.action = '/main/notice.do?method=searchNoticeList';

    return;
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} contnId contnId
 * @param {String} attachFileNm attachFileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (contnId, attachFileNm) {
    if (attachFileNm == null || attachFileNm === "") {
        await $c.win.alert("첨부파일이 없습니다.");
        return;
    }
    const fm = (document.searchForm || { elements: [] });
    $c.util.getComponent('dma_searchBizFormListByCondReq').set('contnId', contnId);
    fm.action = '/main/notice.do?method=downloadFile';
    await scwin.tx_fn_fileDown();
    return;
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};
